Custom objectives
An objective returns a list with a score; lower is better.

get_cooccurrence &lt;- function(design_df, swap) {
  pairs &lt;- unlist(lapply(unique(design_df$block), function(block) {
    combn(sort(as.character(design_df[design_df$block == block, swap])), 2,
          FUN = function(x) paste(x, collapse = ","))
  }))
  return(as.list(table(pairs)))
}

bibd_objective &lt;- function(layout_df, swap, spatial_cols,
                           row_column = "row", col_column = "col", ...) {
  adj &lt;- calculate_adjacency_score(layout_df, swap, row_column, col_column)
  bal &lt;- calculate_balance_score(layout_df, swap, spatial_cols)
  pair_var &lt;- var(as.numeric(get_cooccurrence(layout_df, swap)))
  return(list(score = round(adj + bal + 10 * pair_var, 10)))
}
